from z3 import *

def parse_time(s):
    if s.endswith("AM"):
        h, m = map(int, s[:-2].split(":"))
        suffix = "AM"
    else:
        h, m = map(int, s[:-2].split(":"))
        suffix = "PM"
    if suffix == "PM" and h != 12:
        h += 12
    if suffix == "AM" and h == 12:
        h = 0
    return h * 60 + m

def fmt(t):
    h = (t // 60) % 24
    m = t % 60
    if h == 0:
        h12 = 12
        suffix = "AM"
    elif h < 12:
        h12 = h
        suffix = "AM"
    elif h == 12:
        h12 = 12
        suffix = "PM"
    else:
        h12 = h - 12
        suffix = "PM"
    return f"{h12}:{m:02d}{suffix}"

